From 828857f6709f1b13582049a1ef84eadb07f50c05 Mon Sep 17 00:00:00 2001
From: Jiapeng Chong <jiapeng.chong@linux.alibaba.com>
Date: Wed, 25 Aug 2021 18:37:02 +0800
Subject: [PATCH] platform/x86: asus-wmi: Fix "unsigned 'retval' is never less
 than zero" smatch warning

Eliminate the follow smatch warnings:

drivers/platform/x86/asus-wmi.c:478 panel_od_write() warn: unsigned
'retval' is never less than zero.

drivers/platform/x86/asus-wmi.c:566 panel_od_write() warn: unsigned
'retval' is never less than zero.

drivers/platform/x86/asus-wmi.c:1451 panel_od_write() warn: unsigned
'retval' is never less than zero.

Reported-by: Abaci Robot <abaci@linux.alibaba.com>
Fixes: 98829e84dc67 ("asus-wmi: Add dgpu disable method")
Fixes: 382b91db8044 ("asus-wmi: Add egpu enable method")
Fixes: ca91ea34778f ("asus-wmi: Add panel overdrive functionality")
Signed-off-by: Jiapeng Chong <jiapeng.chong@linux.alibaba.com>
Link: https://lore.kernel.org/r/1629887822-23918-1-git-send-email-jiapeng.chong@linux.alibaba.com
Reviewed-by: Hans de Goede <hdegoede@redhat.com>
Signed-off-by: Hans de Goede <hdegoede@redhat.com>

diff --git a/drivers/platform/x86/asus-wmi.c b/drivers/platform/x86/asus-wmi.c
index 679429d41264..e14fb5fa7324 100644
--- a/drivers/platform/x86/asus-wmi.c
+++ b/drivers/platform/x86/asus-wmi.c
@@ -475,7 +475,7 @@ static int dgpu_disable_write(struct asus_wmi *asus)
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set dgpu disable (retval): 0x%x\n", retval);
 		return -EIO;
 	}
@@ -563,7 +563,7 @@ static int egpu_enable_write(struct asus_wmi *asus)
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set egpu disable (retval): 0x%x\n", retval);
 		return -EIO;
 	}
@@ -1448,7 +1448,7 @@ static int panel_od_write(struct asus_wmi *asus)
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set panel overdrive (retval): 0x%x\n", retval);
 		return -EIO;
 	}
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
platform/x86: asus-wmi: Fix "unsigned 'retval' is never less
 than zero" smatch warning

Eliminate the follow smatch warnings:

drivers/platform/x86/asus-wmi.c:478 panel_od_write() warn: unsigned
'retval' is never less than zero.

drivers/platform/x86/asus-wmi.c:566 panel_od_write() warn: unsigned
'retval' is never less than zero.

drivers/platform/x86/asus-wmi.c:1451 panel_od_write() warn: unsigned
'retval' is never less than zero.

Reported-by: Abaci Robot <abaci@linux.alibaba.com>
Fixes: 98829e84dc67 ("asus-wmi: Add dgpu disable method")
Fixes: 382b91db8044 ("asus-wmi: Add egpu enable method")
Fixes: ca91ea34778f ("asus-wmi: Add panel overdrive functionality")
Signed-off-by: Jiapeng Chong <jiapeng.chong@linux.alibaba.com>
Link: https://lore.kernel.org/r/1629887822-23918-1-git-send-email-jiapeng.chong@linux.alibaba.com
Reviewed-by: Hans de Goede <hdegoede@redhat.com>
Signed-off-by: Hans de Goede <hdegoede@redhat.com>

Here is the root cause:
The bug arises from the incorrect condition checks involving the unsigned variable `retval`. The original checks included a comparison to see if `retval` was less than zero, which is not valid for an unsigned type, leading to unnecessary warnings from the smatch tool. This indicates a misunderstanding of the variable's type and its possible values, which could lead to confusion in error handling logic.

Here is the patch:

 static int dgpu_disable_write(struct asus_wmi *asus)
 {
 	u32 retval;
 	u8 value;
 	int err;

 	/* Don't rely on type conversion */
 	value = asus->dgpu_disable ? 1 : 0;

 	err = asus_wmi_set_devstate(ASUS_WMI_DEVID_DGPU, value, &retval);
 	if (err) {
 		pr_warn("Failed to set dgpu disable: %d\n", err);
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set dgpu disable (retval): 0x%x\n", retval);
 		return -EIO;
 	}

 	sysfs_notify(&asus->platform_device->dev.kobj, NULL, "dgpu_disable");

 	return 0;
 }


 static int egpu_enable_write(struct asus_wmi *asus)
 {
 	u32 retval;
 	u8 value;
 	int err;

 	/* Don't rely on type conversion */
 	value = asus->egpu_enable ? 1 : 0;

 	err = asus_wmi_set_devstate(ASUS_WMI_DEVID_EGPU, value, &retval);

 	if (err) {
 		pr_warn("Failed to set egpu disable: %d\n", err);
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set egpu disable (retval): 0x%x\n", retval);
 		return -EIO;
 	}

 	sysfs_notify(&asus->platform_device->dev.kobj, NULL, "egpu_enable");

 	return 0;
 }


 static int panel_od_write(struct asus_wmi *asus)
 {
 	u32 retval;
 	u8 value;
 	int err;

 	/* Don't rely on type conversion */
 	value = asus->panel_overdrive ? 1 : 0;

 	err = asus_wmi_set_devstate(ASUS_WMI_DEVID_PANEL_OD, value, &retval);

 	if (err) {
 		pr_warn("Failed to set panel overdrive: %d\n", err);
 		return err;
 	}

-	if (retval > 1 || retval < 0) {
+	if (retval > 1) {
 		pr_warn("Failed to set panel overdrive (retval): 0x%x\n", retval);
 		return -EIO;
 	}

 	sysfs_notify(&asus->platform_device->dev.kobj, NULL, "panel_od");

 	return 0;
 }



